const login = async (loginId: string) => {
    const user = await UserService.login(loginId)
    userInfo.value = user
    token.value = 'token-' + user.UserId
    return user
  }

router.beforeEach((to, from, next) => {
  let token = null
  try {
    const userState = JSON.parse(localStorage.getItem('user') || 'null')
    token = userState?.token || null
  } catch { token = null }
  if (to.path === '/login') { next(); return }
  if (!token) { next({ path: '/login', query: { redirect: to.fullPath } }); return }
  next()
})
